style.css:
@-moz-document domain("leetcode.com") {
body, .ant-layout, .ant-layout-content, .ant-layout-sider, .ant-layout-header {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    .ant-card, .ant-card-bordered, .ant-card-body, .ant-card-head {
        background-color: #1e1e1e !important;
        color: #f0f0f0 !important;
    }

    .ant-table, .ant-table-thead > tr > th, .ant-table-tbody > tr > td {
        background-color: #1f1f1f !important;
        color: #ddd !important;
        border-color: #333 !important;
    }

    input, textarea, .ant-input {
        background-color: #2b2b2b !important;
        color: #eee !important;
        border-color: #444 !important;
    }

    button, .ant-btn {
        background-color: #2e2e2e !important;
        color: #eee !important;
        border-color: #444 !important;
    }

    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-thumb {
        background: #555;
    }
    ::-webkit-scrollbar-track {
        background: #1e1e1e;
    }
}
